/bin/bash -lc "cat > /workspace/openai_client.py << 'EOF'
\"\"\"Send private text prompts to OpenAI's Responses API using only the stdlib.

Prompts are treated as private: they are posted only to the Responses API with
"'``store`` disabled so OpenAI does not persist the response for later retrieval,
and they are never written to disk or included in raised error messages.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping, Optional

RESPONSES_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o"
DEFAULT_TIMEOUT = 60.0


class OpenAIClientError(RuntimeError):
    """Raised when a Responses API request cannot be completed."""


def send_private_prompt(
    prompt: str,
    *,
    api_key: [REDACTED_SECRET] = None,
    model: Optional[str] = None,
    instructions: Optional[str] = None,
    timeout: float = DEFAULT_TIMEOUT,
    extra_body: Optional[Mapping[str, Any]] = None,
) -> str:
    """Send a private text prompt and return the model'"'s output text.

    The request always sets "'``store`` to ``False``. Pass ``extra_body`` only for
    additional Responses API fields that do not override privacy settings.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")

    key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY", "")
    if not key:
        raise OpenAIClientError(
            "Missing API key. Set OPENAI_API_KEY or pass api_key."
        )

    chosen_model = model if model is not None else os.environ.get(
        "OPENAI_MODEL", DEFAULT_MODEL
    )

    body: dict[str, Any] = {
        "model": chosen_model,
        "input": prompt,
        "store": False,
    }
    if instructions:
        body["instructions"] = instructions
    if extra_body:
        for field, value in extra_body.items():
            if field in {"input", "store"}:
                raise ValueError(f"extra_body cannot override private field {field!r}")
            body[field] = value

    request = urllib.request.Request(
        RESPONSES_URL,
        data=json.dumps(body).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        raise OpenAIClientError(_http_error_message(exc)) from None
    except urllib.error.URLError as exc:
        raise OpenAIClientError(f"Failed to reach OpenAI Responses API: {exc.reason}") from None
    except json.JSONDecodeError:
        raise OpenAIClientError("Responses API returned invalid JSON.") from None

    text = extract_output_text(payload)
    if text is None:
        raise OpenAIClientError("Responses API returned no output text.")
    return text


def extract_output_text(payload: Mapping[str, Any]) -> Optional[str]:
    """Pull concatenated output_text values from a Responses API payload."""
    chunks: list[str] = []
    for item in payload.get("output") or []:
        if not isinstance(item, Mapping):
            continue
        if item.get("type") not in {None, "message"}:
            continue
        for content in item.get("content") or []:
            if not isinstance(content, Mapping):
                continue
            if content.get("type") in {"output_text", "text"} and isinstance(
                content.get("text"), str
            ):
                chunks.append(content["text"])
    if chunks:
        return "".join(chunks)

    output_text = payload.get("output_text")
    if isinstance(output_text, str) and output_text:
        return output_text
    return None


def _http_error_message(exc: urllib.error.HTTPError) -> str:
    detail = ""
    try:
        raw = exc.read().decode("utf-8", errors="replace")
        parsed = json.loads(raw)
        error = parsed.get("error", parsed)
        if isinstance(error, Mapping):
            detail = str(error.get("message") or error.get("code") or "")
        elif isinstance(error, str):
            detail = error
    except (OSError, UnicodeError, json.JSONDecodeError, AttributeError):
        detail = ""
    status = getattr(exc, "code", "unknown")
    if detail:
        return f"Responses API HTTP {status}: {detail}"
    return f"Responses API HTTP {status}"


if __name__ == "__main__":
    import sys

    prompt = sys.stdin.read()
    sys.stdout.write(send_private_prompt(prompt))
    if not prompt.endswith("'"\\n\"):
        sys.stdout.write(\"\\n\")
